const CATK = { 'Cereais e pães': 'pao', 'Legumes e verduras': 'legumes', 'Frutas': 'fruta', 'Gorduras e óleos': 'azeite', 'Peixe e marisco': 'peixe', 'Carne': 'bife', 'Lácteos': 'leite', 'Bebidas': 'agua', 'Ovos': 'ovo', 'Doces': 'doce', 'Outros': 'molho', 'Pratos prontos': 'marmita', 'Leguminosas': 'feijao', 'Frutos secos e sementes': 'frutossecos', 'Suplementos': 'whey' };
const FP = OS.FoodPics || {};
