const FPN = {}; Object.entries(OS.FoodPhoto || {}).forEach(([k, v]) => { FPN[norm(k)] = v; });
/* ================= catálogo: cada alimento uma vez, com as variantes (cru, cozido, grelhado…) lá dentro ================= */
const GR = [], byName = {}, dupes = {}; DB.forEach(x => { if (!byName[x.name]) byName[x.name] = x; else (dupes[x.name] = dupes[x.name] || []).push(x); });
(OS.FoodCat || []).forEach((r, i) => { const vars = r[4].map(([l, nm]) => ({ l, x: byName[nm] })).filter(v => v.x); if (!vars.length) return;
  const d = vars[0].x, g = { id: 'g' + i, name: r[0], desc: r[1], pic: r[2], bk: r[3], cat: d.cat, vars, def: d, kcal: d.kcal, p: d.p, c: d.c, f: d.f, fib: d.fib, por: d.por, nn: norm(r[0] + ' ' + vars.map(v => v.l + ' ' + v.x.name).join(' ')) };
  vars.forEach(v => (dupes[v.x.name] || []).forEach(d => { d.g = g; d.vl = v.l; if (g.pic) d.pic = g.pic; }));
  vars.forEach(v => { v.x.g = g; v.x.vl = v.l; if (g.pic) { v.x.pic = g.pic; FPN[norm(v.x.name)] = g.pic; } }); if (g.pic) { FPN[norm(g.name)] = g.pic; vars.forEach(v => { FPN[norm(g.name + ' · ' + v.l)] = g.pic; }); } GR.push(g); });
