Diet.gName = gName;
Diet.pic = (name, cat) => { const k = norm(name); if (picCache[k] !== undefined) return picCache[k]; let r = FPN[k] && FPN[k] !== 'W' ? { u: FPN[k], c: /themealdb/.test(FPN[k]) ? 1 : 0 } : null; if (r) return picCache[k] = r;
  for (const [rx, key] of PK) if (rx.test(k) && FP[key]) { r = { u: FP[key], c: /themealdb/.test(FP[key]) ? 1 : 0 }; break; }
  if (!r) for (const [rx, ing] of PICS) if (rx.test(k)) { r = { u: PIC + encodeURIComponent(ing) + '-Small.png', c: 1 }; break; }
  if (!r) { const d = DB.find(x => x.nn === k), key = CATK[cat || (d && d.cat)] || 'marmita'; r = FP[key] ? { u: FP[key] } : { u: '' }; }
  return picCache[k] = r; };
// foto própria de cada alimento: procurada na Wikipédia em português a partir deste aparelho, guardada e sincronizada
OS.ONE_DEF.foodpics = { m: {} };
const STW = new Set('cru crua crus cruas cozido cozida cozidos cozidas grelhado grelhada frito frita fritos fritas assado assada refogado refogada congelado congelada com sem de da do dos das e tipo para pre pronto pronta unidade media inteiro inteira posta file capa gordura pele sal oleo soja enlatado enlatada drenado drenada conserva em calda industrializado industrializada sabor'.split(' '));
Diet.picQuery = name => { let w = norm(name).replace(/[(),%/.0-9]/g, ' ').split(/\s+/).filter(x => x.length > 2 && !STW.has(x)); if (w[0] === 'carne' && w[1] === 'bovina') w = w.slice(2).concat('carne'); return w.slice(0, 4).join(' '); };
