const tl = x => { if (!(OS.Lang && OS.Lang.on())) return x.nn; const c = OS.Lang.code(); if (x._lc !== c) { x._lc = c; x._nt = x.nn + ' ' + norm(OS.Lang.t(x.name) + (x.vars ? ' ' + x.vars.map(v => OS.Lang.t(v.l)).join(' ') : '')); } return x._nt; };
Diet.search = (q, lim = 40) => { const w = norm(q).split(/\s+/).filter(Boolean); if (!w.length) return [];
  const score = x => { let s = 0; const nn = tl(x); w.forEach(t => { const i = nn.indexOf(t); if (i < 0) s -= 1e3; else s += (i === 0 ? 30 : nn[i - 1] === ' ' || nn[i - 1] === ',' ? 15 : 3); }); if (x.uid) s += 25; s -= (x.vars ? norm(x.name).length : x.nn.length) / 20; if (x.vars) s -= (+x.id.slice(1)) * .004 + (x.cat === 'Pratos prontos' ? 4 : 0); if (!x.vars && /\bcru|crua\b/.test(x.nn) && !w.some(t => t.startsWith('cru'))) s -= 6; if (/coracao|figado|moela|lingua|bucho|orelha|rabo|toucinho|dobradinha|sarapatel/.test(x.nn) && !w.some(t => /coracao|figado|moela|lingua|bucho|orelha|rabo/.test(t))) s -= 12; return s; };
  const seen = new Set(); return [...userFoods(), ...brHere(), ...ffHere(), ...GR, ...DB.filter(x => !x.g)].map(x => [score(x) + (x.vars ? 8 : 0), x]).filter(([s]) => s > -1e3 / 2).sort((a, b) => b[0] - a[0]).map(x => x[1]).filter(x => !seen.has(x.id) && seen.add(x.id)).slice(0, lim); };
